'use strict';
window.HRAnnual={mount(page,{context,openRecord}){
 const $=id=>document.getElementById(id),node=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n};
 page.insertAdjacentHTML('beforeend',`<div class="annual-filters field-grid"><div><label for="annualYear">年度</label><select id="annualYear"></select></div><div><label for="annualSearch">員工姓名／編號</label><input id="annualSearch"></div><div><label for="annualDepartment">部門</label><select id="annualDepartment"><option value="">全部部門</option></select></div><div><label for="annualFirstStatus">上半年狀態</label><select id="annualFirstStatus"></select></div><div><label for="annualSecondStatus">下半年狀態</label><select id="annualSecondStatus"></select></div></div><div id="annualSummary" class="annual-summary"></div><p class="muted">統計為本年度授權範圍；下方條件僅篩選對照清單，不換算或平均不同量表分數。</p><div class="toolbar"><button type="button" id="exportAnnual" class="secondary">匯出年度 Excel</button></div><div class="table-wrap"><table class="annual-table"><thead><tr><th>員工</th><th>部門</th><th>上半年分數／狀態</th><th>下半年分數／狀態</th><th>查看</th></tr></thead><tbody id="annualRows"></tbody></table></div><div class="toolbar annual-pager"><button type="button" id="annualPrev" class="secondary">上一頁</button><span id="annualPage"></span><button type="button" id="annualNext" class="secondary">下一頁</button><label for="annualSize">每頁筆數</label><select id="annualSize"><option>10</option><option selected>20</option><option>50</option></select></div><p id="annualMessage" role="status"></p>`);
 const heading=node('div');heading.className='page-heading';page.prepend(heading);const oldTools=$('exportAnnual').parentElement;heading.append(page.querySelector('h2'),$('exportAnnual'));oldTools.remove();
 let pageNumber=1,generation=0,ready=false,timer;const storageKey='stage10-annual-'+context.id,filterIds=['annualYear','annualSearch','annualDepartment','annualFirstStatus','annualSecondStatus','annualSize'];let restored=null;try{restored=JSON.parse(window.HRGoogleCache.getItem(storageKey)||'null')}catch{}
 function query(){return {year:$('annualYear').value,search:$('annualSearch').value,department:$('annualDepartment').value,firstStatus:$('annualFirstStatus').value,secondStatus:$('annualSecondStatus').value,page:String(pageNumber),size:$('annualSize').value}}
 function persist(){window.HRGoogleCache.setItem(storageKey,JSON.stringify({page:pageNumber,filters:Object.fromEntries(filterIds.map(id=>[id,$(id).value]))}))}
 async function refresh(){const id=++generation;try{const values=ready?query():{};const response=await fetch('/api/annual?'+new URLSearchParams(values));const data=await response.json();if(!response.ok)throw Error(data.error||'年度資料載入失敗');if(id!==generation)return;
  const options=(select,list,value)=>{select.replaceChildren(...list.map(([v,label])=>new Option(label,v)));select.value=value};
  options($('annualYear'),data.years.map(y=>[y,y+' 年']),data.year||'');options($('annualDepartment'),[['','全部部門'],...data.departments.map(d=>[d,d])],values.department||'');
  if(ready&&values.department&&!data.departments.includes(values.department)){$('annualDepartment').value='';return refresh()}
  if(!ready){for(const key of ['annualFirstStatus','annualSecondStatus'])options($(key),[['','全部狀態'],...Object.entries(data.statuses)],'');ready=true;if(restored){for(const [key,value]of Object.entries(restored.filters||{})){if(key==='annualDepartment'&&value&&![...$(key).options].some(o=>o.value===value))$(key).add(new Option(value,value));if(filterIds.includes(key)&&($(key).tagName!=='SELECT'||[...$(key).options].some(o=>o.value===value)))$(key).value=value}pageNumber=restored.page||1;restored=null;return refresh()}}
  pageNumber=data.page;$('annualSummary').replaceChildren(...data.summary.map((s,i)=>{const card=node('section');card.className='annual-half';card.append(node('h3',s.period?window.HRUI.period(s.period):(i?'下半年':'上半年')));if(s.available){const dl=node('dl');dl.className='annual-metrics';for(const [title,value]of [['應填人數',s.required],['已完成',s.completed],['未完成',s.incomplete],['完成率',s.completionRate+'%']]){const group=node('div');group.append(node('dt',title),node('dd',value));dl.append(group)}card.append(dl)}else card.append(node('p',s.restricted?'本期未授權':'尚未建立'));return card}));
  $('annualRows').replaceChildren(...data.rows.map(e=>{const tr=node('tr'),identity=node('td');identity.append(node('strong',e.name),node('small',e.employeeId));tr.append(identity,node('td',e.department));for(const h of e.halves){const td=node('td');td.append(node('strong',h.score===null?h.label:String(h.score)),node('small',h.score===null?'':h.label),node('small',h.formRole==='supervisor'?'主管人員':h.formRole==='staff'?'一般職員':''));td.dataset.annualStatus=h.status;tr.append(td)}const actions=node('td');const group=node('div');group.className='workflow-row-actions';e.halves.forEach((h,i)=>{if(!h.formRole)return;const b=node('button',i?'下半年':'上半年');b.type='button';b.className='secondary';b.setAttribute('aria-label','查看'+(i?'下半年':'上半年')+'完整面談表');b.dataset.annualEmployee=e.employeeId;b.dataset.annualPeriod=h.period;b.onclick=()=>openRecord(e.employeeId,h.period).catch(error=>$('annualMessage').textContent=error.message);group.append(b)});actions.append(group);tr.append(actions);return tr}));
  if(!data.rows.length){const tr=node('tr'),td=node('td','沒有符合條件的年度資料');td.colSpan=5;tr.append(td);$('annualRows').append(tr)}$('annualPage').textContent=pageNumber+' / '+data.pages+'（共 '+data.total+' 人）';$('annualPrev').disabled=pageNumber===1;$('annualNext').disabled=pageNumber===data.pages;$('exportAnnual').disabled=!context.permissions.includes('word')||!data.year||!data.total;$('annualMessage').textContent='';persist();page.dataset.annualReady='true';
 }catch(e){if(id===generation)$('annualMessage').textContent=e.message}}
 for(const id of filterIds)$(id).addEventListener(id==='annualSearch'?'input':'change',e=>{if(e.isComposing)return;pageNumber=1;clearTimeout(timer);if(id==='annualSearch')timer=setTimeout(refresh,180);else refresh()});$('annualSearch').addEventListener('compositionend',()=>{pageNumber=1;refresh()});$('annualPrev').onclick=()=>{pageNumber--;refresh()};$('annualNext').onclick=()=>{pageNumber++;refresh()};
 $('exportAnnual').hidden=!context.permissions.includes('word');$('exportAnnual').onclick=async()=>{try{const values=query();delete values.page;delete values.size;const r=await fetch('/api/annual/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});if(!r.ok)throw Error((await r.json()).error||'年度匯出未完成');const url=URL.createObjectURL(await r.blob()),a=node('a');a.href=url;a.download='年度考績對照_'+values.year+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('annualMessage').textContent='年度 Excel 已匯出，未完成與免填不以0分表示。'}catch(e){$('annualMessage').textContent=e.message}};
 return {open:refresh};
}};
